// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { PlayIcon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { ALL, BROKEN, CAPTIONS, ERROR, REMOTE, REMOTE_MATCHES, ROLES } from './script'

const WALK = 1.4

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  click,
  type,
  wait,
  count,
  cursorOut,
}) => {
  const dot = q('dot')
  const points = ROLES.map((role) => {
    const point = pos(`row-${role.id}`, 0, 0.5)
    return { x: point.x + 5, y: point.y - 4 }
  })
  const walk = (matches: (index: number) => boolean) => {
    tl.set(dot, { x: points[0].x, y: points[0].y - 16 })
    tl.to(dot, { opacity: 1, y: points[0].y, duration: 0.2 })
    tl.to(dot, { motionPath: { path: points, curviness: 0.4 }, duration: WALK, ease: 'none' })
    const start = tl.duration() - WALK
    ROLES.forEach((_, index) => {
      const at = start + (index / (ROLES.length - 1)) * WALK
      if (matches(index)) {
        tl.to(
          q(`row-${ROLES[index].id}`),
          {
            backgroundColor: 'rgba(45,212,191,0.16)',
            borderColor: 'rgba(45,212,191,0.7)',
            duration: 0.2,
          },
          at,
        )
        tl.fromTo(dot, { scale: 1.8 }, { scale: 1, duration: 0.25, ease: 'power2.out' }, at)
      }
    })
    tl.to(dot, { opacity: 0, duration: 0.2 }, start + WALK)
  }
  const unglow = () =>
    tl.to(qa('row'), {
      backgroundColor: 'rgba(255,255,255,1)',
      borderColor: 'rgba(0,0,0,0.08)',
      duration: 0.25,
    })

  step(0)
  move('input', { ax: 0.15 })
  click('input')
  type('input-text', ALL, { speed: 0.03 })
  move('test', { at: '+=0.1' })
  click('test')

  step(1, '+=0.2')
  walk(() => true)
  tl.fromTo(q('result'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<')
  count('match-count', ROLES.length, { at: '<', duration: 0.4, suffix: ' matches' })
  tl.fromTo(
    qa('sample'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.06 },
    '<0.1',
  )

  step(2, '+=0.5')
  move('input', { ax: 0.6 })
  click('input')
  type('input-text', REMOTE, { speed: 0.03 })
  unglow()
  move('test', { at: '+=0.1' })
  click('test')
  walk((index) => ROLES[index].remote)
  count('match-count', REMOTE_MATCHES.length, {
    from: ROLES.length,
    at: '<',
    duration: 0.4,
    suffix: ' matches',
  })
  tl.to(
    qa('sample-other'),
    {
      height: 0,
      opacity: 0,
      paddingTop: 0,
      paddingBottom: 0,
      marginBottom: 0,
      borderWidth: 0,
      duration: 0.3,
      stagger: 0.04,
    },
    '<',
  )

  step(3, '+=0.5')
  move('input', { ax: 0.6 })
  click('input')
  type('input-text', BROKEN, { speed: 0.05 })
  move('test', { at: '+=0.1' })
  click('test')
  unglow()
  tl.to(q('result'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(q('error'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<0.1')
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="XPath Tester running expressions against a careers page and showing matches and an error"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app/careers"
        panelWidth={236}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-2 p-2.5">
              <div className="flex gap-1.5">
                <div
                  data-d="input"
                  className="flex h-7 min-w-0 flex-1 items-center rounded-lg border border-line bg-canvas/80 px-2 font-mono text-[9px] text-ink"
                >
                  <span data-d="input-text" className="demo-caret truncate" />
                </div>
                <span
                  data-d="test"
                  className="flex h-7 items-center gap-1 rounded-lg bg-[var(--accent)] px-2 text-[10px] font-medium text-canvas"
                >
                  <PlayIcon className="size-3" /> Test
                </span>
              </div>
              <div data-d="result" className="space-y-1 opacity-0">
                <span
                  data-d="match-count"
                  className="inline-block rounded-full bg-white/10 px-2 py-0.5 text-[9.5px] text-ink"
                >
                  0 matches
                </span>
                {ROLES.map((role) => (
                  <code
                    key={role.id}
                    data-d={role.remote ? 'sample' : 'sample sample-other'}
                    className="block h-[18px] overflow-hidden rounded-md border border-line bg-canvas/60 px-2 py-0.5 font-mono text-[9px] text-ink-soft"
                  >
                    li#{role.id}
                  </code>
                ))}
              </div>
              <p
                data-d="error"
                className="absolute inset-x-2.5 top-[46px] rounded-lg border border-rose/40 bg-rose/10 p-2 font-mono text-[8.5px] leading-relaxed text-rose opacity-0"
              >
                {ERROR}
              </p>
            </div>
          </div>
        }
      >
        <div className="h-full bg-[#fafafa] px-4 pt-3 text-[#111]">
          <p className="text-[8px] font-semibold uppercase tracking-[0.2em] text-[#7c3aed]">
            Careers
          </p>
          <h3 className="text-[15px] font-bold tracking-tight">Open roles</h3>
          <ul className="mt-2 space-y-1.5">
            {ROLES.map((role) => (
              <li
                key={role.id}
                data-d={`row row-${role.id}`}
                data-remote={role.remote ? 'true' : 'false'}
                className="role flex items-center justify-between rounded-md border border-black/[0.08] bg-white py-1.5 pl-5 pr-2 text-[9.5px]"
              >
                <span className="font-medium">{role.title}</span>
                <span className="text-[8px] text-[#777]">{role.remote ? 'Remote' : 'London'}</span>
              </li>
            ))}
          </ul>
        </div>
      </BrowserChrome>
      <span
        data-d="dot"
        className="absolute left-0 top-0 z-30 size-2 rounded-full bg-[#2dd4bf] opacity-0 shadow-[0_0_12px_#2dd4bf]"
      />
    </DemoStage>
  )
}
